/**
 * Returns a calIDateTime that corresponds to the current time in the user's
 * default timezone.
 *
 * @returns {calIDateTime}
 */
now() {
  const date = dtz.jsDateToDateTime(new Date());
  return date.getInTimezone(dtz.defaultTimezone);
},
